def main():
 h=read(D/'heavy_empirical_replica_table.json');factor=h['safe_factor'];witness=read(D/'witnesses/mix_03_I3__B6.json');row=next(r for r in witness['rows'] if r['Specialist_regime']==H);fit=witness['fits'][H];cpu=[];observed=[];perfamily=[];checks=[]
 frozen=read(V/'validation_freeze.json');planned=next(s for s in frozen['slots'] if s['context']=='mix_03_I3/B6' and s['Specialist_regime']==H)
 assert planned['deployment']==row['replicas'];expected=sum(row['replicas'].values())
 for m,n in row['replicas'].items():cpu.append({'model_identity':m,'replica_count':n,'M_x_mib':h['memory_table_mib'][m][str(n)],'M_safe_x_mib':factor*h['memory_table_mib'][m][str(n)],'safe_factor':factor,'budget_mib':49140,'memory_reference':ref(D/'heavy_empirical_replica_table.json')})
 total=math.fsum(r['M_safe_x_mib'] for r in cpu);rawtotal=math.fsum(r['M_x_mib'] for r in cpu);assert abs(total-row['safe_memory_mib'])<1e-8
 for rep in [1,2,3]:
  p=V/f'raw_runs/context1_H_rep{rep}.json';raw=read(p);idle=raw['postwarm_idle'];samples=raw['telemetry']['samples'];identities=raw['worker_identities'];pids={v['pid'] for v in identities.values()};assert raw['valid_session'] and raw['slot']['deployment']==row['replicas'];assert len(identities)==len(pids)==expected
  obs=statistics.mean(s['owned_used_mib'] for s in idle);summed=0.
  for m,n in row['replicas'].items():
   owned={v['pid'] for v in identities.values() if v['family']==m};assert len(owned)==n
   values=[sum(p['used_mib'] for p in s['processes'] if p['pid'] in owned) for s in idle];actual=statistics.mean(values);pred=h['memory_table_mib'][m][str(n)];summed+=actual
   perfamily.append({'repetition':rep,'model_identity':m,'replica_count':n,'CPU_M_x_mib':pred,'observed_idle_M_x_mib':actual,'delta_idle_mib':actual-pred,'delta_safe_mib':factor*(actual-pred),'owned_PIDs':sorted(owned),'owned_peak_mib':max(sum(p['used_mib'] for p in s['processes'] if p['pid'] in owned) for s in samples),'raw':ref(p)})
  assert abs(summed-obs)<1e-8 and not any(s['foreign_pids'] for s in samples)
  old=next(r for r in read(V/'validation_rows.json') if r['run_id']==raw['slot']['run_id']);assert abs(factor*obs-old['safe_idle_memory_mib'])<1e-8
  observed.append({'repetition':rep,'observed_idle_owned_mib':obs,'observed_idle_device_mib':statistics.mean(s['used_mib'] for s in idle),'observed_peak_owned_mib':max(s['owned_used_mib'] for s in samples),'observed_peak_device_mib':max(s['used_mib'] for s in samples),'safe_factor':factor,'observed_safe_idle_mib':factor*obs,'budget_mib':49140,'OBSERVED_BUDGET_EXCEEDED':factor*obs>49140,'safe_excess_mib':factor*obs-49140,'CPU_vs_observed_safe_delta_mib':factor*obs-total,'planned_worker_count':expected,'runtime_worker_count':len(identities),'unique_NVML_compute_PIDs_during_idle':[len(s['processes']) for s in idle],'all_idle_PIDs_exactly_planned':all({p['pid'] for p in s['processes']}==pids for s in idle),'foreign_processes':False,'calculation':'same frozen factor times SUM owned independent worker NVML residency; no device-total/peak/host-RSS substitution','raw':ref(p)})
  checks.append({'repetition':rep,'CPU_sum_reproduced':True,'x2_OCR_table_loaded_correctly_and_observed_exactly_matches':all(x['delta_idle_mib']==0 for x in perfamily if x['repetition']==rep and x['model_identity'].startswith('baudm/')),'safe_factor_same':True,'no_duplicate_unplanned_residency':True})
 olddir=ROOT/'results/module13_real_specialists/raw13b';mms=next(m for m in h['models'] if m.startswith('facebook/mms'))
 original=[read(olddir/f'lid__facebook--mms-lid-256__latency__r{i}.summary.json') for i in [1,2,3]]
 current=[read(D/f'raw_runs/path4_lid_x1_rep{i}.json') for i in [1,2,3]]
 version_keys=['dtype','framework_versions','attention','TF32_matmul','TF32_cudnn','threads','parameter_count','directory']
 invariant={k:all(o['ready'].get(k)==r['worker_identities'][mms+'#0']['READY'].get(k) for o,r in zip(original,current)) for k in version_keys}
 assert all(invariant.values())
 source_refs=[ref(olddir/f'lid__facebook--mms-lid-256__latency__r{i}.summary.json') for i in [1,2,3]]+[ref(D/f'raw_runs/path4_lid_x1_rep{i}.json') for i in [1,2,3]]
 result={'at_utc':now(),'context':'mix_03_I3/B6','regime':H,'CPU_FEASIBILITY_CERTIFIED':bool(fit['certificate']['passed'] and row['max_rho']<=.8+1e-9 and total<=49140 and fit['global_gap_seconds']<=1e-8),'certificate_scope':'Exactly the supplied measured-state table and frozen CPU J/rho model; not a guarantee of subsequently observed post-full-workload residency or stability.','CPU_idle_sum_mib':rawtotal,'CPU_safe_sum_mib':total,'budget_mib':49140,'CPU_safe_slack_mib':49140-total,'CPU_rows':cpu,'GPU_observations':observed,'per_family_observations':perfamily,'checks':checks,'causes':{'stale_M_x':{'status':'CONFIRMED_SCOPE_STALENESS_MMS_M1','detail':'Legacy MMS M1=4540 was observed after one priming sample BEFORE the 30-sample latency cohort. Old cohort peaks already exceed that idle snapshot. 14D froze this M1 although auxiliary warmed x1 references observed 5688,6252,5292. 14E whole-workload warmup sees 5340,5904,5292. The same checkpoint/precision/framework holds; this is under-warmed residency reused for a different warming scope, not a new model.','legacy_idle_values':[o['idle_model_vram_mib'] for o in original],'legacy_inference_peaks':[o['peak_inference_vram_mib'] for o in original],'14D_warmed_x1_values':[statistics.mean(s['owned_used_mib'] for s in r['postwarm_idle']) for r in current],'14E_mms_idle_values':[r['observed_idle_M_x_mib'] for r in perfamily if r['model_identity']==mms]},'x2_table_not_loaded':{'status':'RULED_OUT','detail':'CPU uses all four exact 14D M2 entries; each agrees bit-for-value with each observed OCR family sum. MMS in this optimum is x1, so M2=10998 is correctly not charged.'},'safe_factor_mismatch':{'status':'RULED_OUT','factor':factor},'runtime_drift':{'status':'SMALL_OTHER_FAMILY_RESIDENCY_VARIATION_CONFIRMED; MODEL_OR_FRAMEWORK_DRIFT_NOT_SUPPORTED','invariant_metadata':invariant,'detail':'Phi x2 and Whisper/Roberta vary around their historic postwarm snapshots. Variable input/allocator residency is plausible; telemetry alone cannot separate allocator caches/workspaces from other per-process CUDA allocations. Do not claim an unobserved allocator mechanism as proved.'},'duplicated_residency_process':{'status':'RULED_OUT','planned_and_observed_workers':expected},'measurement_semantics_mismatch':{'status':'CONFIRMED','detail':'Legacy pre-cohort one-sample idle M1 versus multi-path plus full warmup postwarm_idle; GPU and CPU both compute owned idle*factor correctly, but the table anchors have heterogeneous warming coverage. Correct the observation scope rather than the multiplier/budget.'},'numerical_tolerance':{'status':'RULED_OUT','detail':'GPU/CPU safe deltas of hundreds to thousands MiB dwarf 1e-6 MiB arithmetic tolerances.'},'device_or_peak_double_count':{'status':'RULED_OUT','detail':'GPU safe calculation uses owned idle only. Device overhead and measurement peak are recorded separately, not added twice.'}},'MMS_sources':source_refs,'budget_raised':False,'Module9_changed':False}
 save('memory_reconciliation.json',result);csvsave('cpu_memory_breakdown.csv',cpu);csvsave('gpu_memory_comparison.csv',perfamily);csvsave('gpu_memory_totals.csv',observed)
 print('RECONCILED',result['CPU_FEASIBILITY_CERTIFIED'],rawtotal,total,'MMS scope mismatch',flush=True)
